/* ==== js/ui.js ==== */
try{
/* ui.js — navegación espacial con D-pad, modales, menús y toasts. */
(function(){
"use strict";

var App = window.App;
var K = App.K;
var ui = App.ui = App.ui || {};

/* ================= Scroll helper ================= */
function scrollIntoViewSmart(el){
  if(!el) return;
  var p = el.parentNode;
  while(p && p !== document.body){
    var cs = window.getComputedStyle(p);
    var oy = cs.overflowY, ox = cs.overflowX;
    var r = el.getBoundingClientRect(), pr = p.getBoundingClientRect();
    if((oy === "auto" || oy === "scroll") && p.scrollHeight > p.clientHeight){
      var top = r.top - pr.top + p.scrollTop;
      var target = top - (p.clientHeight - r.height) / 2;
      p.scrollTop = Math.max(0, target);
    }
    if((ox === "auto" || ox === "scroll") && p.scrollWidth > p.clientWidth){
      var left = r.left - pr.left + p.scrollLeft;
      var pad = 60;
      if(r.left < pr.left + pad) p.scrollLeft = Math.max(0, left - pad);
      else if(r.right > pr.right - pad) p.scrollLeft = left + r.width - p.clientWidth + pad;
    }
    p = p.parentNode;
  }
}
ui.scrollIntoView = scrollIntoViewSmart;

/* ================= FocusGrid (navegación espacial) =================
 * Gestiona el foco entre los elementos .focusable de un contenedor usando su
 * posición en pantalla, así sirve igual para listas, rejillas o filas mixtas.
 */
function FocusGrid(container, opts){
  this.container = container;
  this.opts = opts || {};
  this.items = [];
  this.index = 0;
  this.refresh();
  /* Ratón / táctil (PC, móvil, Android TV con puntero): clic = enfocar + OK.
   * Un solo listener por contenedor; apunta siempre a la última rejilla creada sobre él. */
  container._fg = this;
  if(!container._fgClick){
    container._fgClick = true;
    container.addEventListener("click", function(ev){
      var g = container._fg; if(!g) return;
      var el = ev.target.closest ? ev.target.closest(".focusable") : null;
      if(!el) return;
      g.refresh(false);
      var i = g.items.indexOf(el);
      if(i < 0) return;
      ev.preventDefault();
      if(document.body.classList.contains("zone-header") && App.focusContent) App.focusContent();
      /* táctil: tocar no debe recentrar la página (salto brusco); la rueda/D-pad sí */
      ui._noScroll = document.body.classList.contains("touch");
      try{ g.focus(i); }finally{ ui._noScroll = false; }
      if(el.tagName === "INPUT"){ el.focus(); return; }
      if(g.opts.onSelect) g.opts.onSelect(i, el);
    });
  }
}
FocusGrid.prototype.refresh = function(keepIndex){
  this.items = Array.prototype.slice.call(this.container.querySelectorAll(".focusable"))
    .filter(function(el){ return el.offsetParent !== null || el.getClientRects().length; });
  if(this.index >= this.items.length) this.index = Math.max(0, this.items.length - 1);
  if(keepIndex !== false) this.paint();
  return this;
};
FocusGrid.prototype.paint = function(){
  var self = this;
  this.items.forEach(function(el, i){ el.classList.toggle("focused", i === self.index); });
};
FocusGrid.prototype.focus = function(i, silent){
  if(!this.items.length) return;
  this.index = Math.max(0, Math.min(i, this.items.length - 1));
  this.paint();
  var el = this.items[this.index];
  if(!ui._noScroll) scrollIntoViewSmart(el);
  if(!silent && this.opts.onFocus) this.opts.onFocus(this.index, el);
};
FocusGrid.prototype.blur = function(){
  this.items.forEach(function(el){ el.classList.remove("focused"); });
};
FocusGrid.prototype.current = function(){ return this.items[this.index] || null; };

FocusGrid.prototype.move = function(dir){
  var cur = this.items[this.index];
  if(!cur) return false;
  var a = cur.getBoundingClientRect();
  var ax = a.left + a.width/2, ay = a.top + a.height/2;
  var best = -1, bestScore = Infinity;
  for(var i = 0; i < this.items.length; i++){
    if(i === this.index) continue;
    var b = this.items[i].getBoundingClientRect();
    var bx = b.left + b.width/2, by = b.top + b.height/2;
    var dx = bx - ax, dy = by - ay, primary, secondary;
    if(dir === "up"){ if(b.bottom > a.top + 2) continue; primary = -dy; secondary = Math.abs(dx); }
    else if(dir === "down"){ if(b.top < a.bottom - 2) continue; primary = dy; secondary = Math.abs(dx); }
    else if(dir === "left"){ if(b.right > a.left + 2) continue; primary = -dx; secondary = Math.abs(dy); }
    else { if(b.left < a.right - 2) continue; primary = dx; secondary = Math.abs(dy); }
    var score = primary + secondary * 2.5;
    if(score < bestScore){ bestScore = score; best = i; }
  }
  if(best >= 0){ this.focus(best); return true; }
  return false;
};

FocusGrid.prototype.handleKey = function(k){
  var dir = k === K.UP ? "up" : k === K.DOWN ? "down" : k === K.LEFT ? "left" : k === K.RIGHT ? "right" : null;
  if(dir){
    if(!this.items.length){ if(dir === "left"){ App.focusHeader(); return true; } return false; }
    if(this.move(dir)) return true;
    if(this.opts.onEdge){ var r = this.opts.onEdge(dir); if(r !== undefined) return !!r; }
    if(dir === "left"){ App.focusHeader(); return true; }   // borde izquierdo → rail lateral
    return true; // ▲ y demás bordes: se quedan (no van al rail)
  }
  if(k === K.OK){
    var el = this.items[this.index];
    if(el && this.opts.onSelect){ this.opts.onSelect(this.index, el); return true; }
  }
  return false;
};
ui.FocusGrid = FocusGrid;

/* ================= Modales ================= */
var stack = [];

function closeTop(value){
  var m = stack.pop(); if(!m) return;
  if(m.el.parentNode) m.el.parentNode.removeChild(m.el);
  if(m.onClose) m.onClose(value);
}

/* opts: {title, html, buttons:[{label,value}], vertical, onClose(value), onKey(k)} */
ui.modal = function(opts){
  var el = document.createElement("div");
  el.className = "modal-backdrop";
  var btns = (opts.buttons || [{label:App.t("ui.ok"), value:true}]).map(function(b, i){
    return '<div class="btn focusable" data-i="'+i+'">'+App.esc(b.label)+'</div>';
  }).join("");
  el.innerHTML =
    '<div class="modal'+(opts.vertical?' vertical':'')+(opts.wide?' wide':'')+'">'+
      (opts.title ? '<h2>'+App.esc(opts.title)+'</h2>' : '')+
      (opts.html ? '<div class="modal-body">'+opts.html+'</div>' : '')+
      '<div class="modal-buttons">'+btns+'</div>'+
    '</div>';
  document.body.appendChild(el);
  /* Ratón/táctil: pulsar fuera del cuadro cierra (como Atrás). Solo fuera de la TV. */
  if(!App.isTizen()){
    el.addEventListener("click", function(ev){
      if(ev.target !== el) return;
      var top = stack[stack.length - 1];
      if(top && top.el === el) closeTop(top.cancelValue === undefined ? null : top.cancelValue);
    });
  }
  var grid = new FocusGrid(el.querySelector(".modal-buttons"), {
    onEdge: function(){ return true; },
    onSelect: function(i){ closeTop((opts.buttons || [{value:true}])[i].value); }
  });
  var start = 0;
  (opts.buttons || []).forEach(function(b, i){ if(b.selected) start = i; });
  grid.focus(start, true);
  var m = { el: el, grid: grid, onClose: opts.onClose, onKey: opts.onKey, cancelValue: opts.cancelValue };
  stack.push(m);
  return { close: function(v){ if(stack[stack.length-1] === m) closeTop(v); }, el: el };
};

ui.isModalOpen = function(){ return stack.length > 0; };

/* main.js llama a esto cuando hay modal abierto */
ui.modalKey = function(k, e){
  var m = stack[stack.length-1]; if(!m) return false;
  if(m.onKey && m.onKey(k, e)) return true;
  if(App.isBack(k)){ closeTop(m.cancelValue === undefined ? null : m.cancelValue); return true; }
  m.grid.handleKey(k);
  return true;
};

ui.confirm = function(title, text, yes, no){
  return new Promise(function(resolve){
    ui.modal({
      title: title, html: text ? '<p>'+App.esc(text)+'</p>' : "",
      buttons: [{label: yes || App.t("ui.yes"), value: true}, {label: no || App.t("ui.no"), value: false}],
      cancelValue: false, onClose: function(v){ resolve(!!v); }
    });
  });
};

/* items: [{label, value, selected, hint}] → Promise<value|null> */
ui.menu = function(title, items){
  return new Promise(function(resolve){
    ui.modal({
      title: title, vertical: true,
      buttons: items.map(function(it){
        return { label: (it.selected ? "● " : "") + it.label, value: it.value, selected: it.selected };
      }),
      cancelValue: null, onClose: function(v){ resolve(v === undefined ? null : v); }
    });
  });
};

/* ================= Toast ================= */
var toastEl, toastTimer;
ui.toast = function(msg, ms){
  if(!toastEl){
    toastEl = document.createElement("div");
    toastEl.className = "toast";
    document.body.appendChild(toastEl);
  }
  toastEl.textContent = msg;
  toastEl.setAttribute("role", "status");
  toastEl.classList.add("on");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(function(){ toastEl.classList.remove("on"); }, ms || 3000);
};

/* ================= Estados de pantalla ================= */
ui.loading = function(el, msg){
  el.innerHTML = '<div class="center"><div class="spinner"></div><p>'+App.esc(msg || App.t("ui.loading"))+'</p></div>';
};
ui.error = function(el, title, msg){
  el.innerHTML = '<div class="center err"><h2>'+App.esc(title)+'</h2><p>'+App.esc(msg || "")+'</p></div>';
};
ui.empty = function(el, title, msg){
  el.innerHTML = '<div class="center"><h2>'+App.esc(title)+'</h2><p>'+(msg || "")+'</p></div>';
};

/* Placeholder de carátula: iniciales sobre color estable derivado del título */
ui.placeholderStyle = function(title){
  var h = 0, s = String(title || "?");
  for(var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;
  return "background:linear-gradient(135deg,hsl("+h+",45%,28%),hsl("+((h+40)%360)+",50%,16%))";
};
ui.initials = function(title){
  var w = String(title || "?").replace(/[^\wÀ-ÿ ]/g, " ").trim().split(/\s+/);
  return ((w[0] || "?").charAt(0) + (w[1] ? w[1].charAt(0) : "")).toUpperCase();
};

})();

}catch(__e){ if(window.console) console.error("[bundle] js/ui.js", __e); }
;
/* ==== js/torbox.js ==== */
try{
/* torbox.js — cliente de la API de TorBox. search.js añade search/addMagnet/etc. */
(function(){
"use strict";

var App = window.App;
var API = "https://api.torbox.app/v1/api";

var tb = App.torbox = App.torbox || {};
tb.API = API;
tb.SOURCES = ["torrents", "usenet", "webdl"];
tb.SOURCE_LABEL = { torrents: "Torrents", usenet: "Usenet", webdl: "Web" };
tb.ID_FIELD = { torrents: "torrent_id", usenet: "usenet_id", webdl: "web_id" };

function token(){ return App.settings.get("torboxToken") || ""; }
tb.token = token;
tb.hasToken = function(){ return !!token(); };

/* opts: {method, body (objeto → JSON), form (objeto → FormData), headers, base} */
tb.api = function(path, opts){
  opts = opts || {};
  var headers = opts.headers || {};
  headers["Authorization"] = "Bearer " + token();
  var body;
  if(opts.form){
    body = new FormData();
    Object.keys(opts.form).forEach(function(k){
      if(opts.form[k] !== undefined && opts.form[k] !== null) body.append(k, opts.form[k]);
    });
  } else if(opts.urlencoded){
    headers["Content-Type"] = "application/x-www-form-urlencoded";
    body = Object.keys(opts.urlencoded).filter(function(k){
      return opts.urlencoded[k] !== undefined && opts.urlencoded[k] !== null;
    }).map(function(k){ return encodeURIComponent(k) + "=" + encodeURIComponent(opts.urlencoded[k]); }).join("&");
  } else if(opts.body){
    headers["Content-Type"] = "application/json";
    body = JSON.stringify(opts.body);
  }
  return App.net.fetch((opts.base || API) + path, { method: opts.method || "GET", headers: headers, body: body })
    .then(function(r){
      return r.text().then(function(txt){
        var j; try{ j = txt ? JSON.parse(txt) : {}; }catch(e){ j = { detail: txt }; }
        if(!r.ok || j.success === false){
          var err = new Error((j && (j.detail || j.error)) || ("HTTP " + r.status));
          err.status = r.status; err.body = j;
          console.warn("[TorBox API] " + (opts.method || "GET") + " " + path.split("?")[0] + " → " + r.status + " " + err.message);
          throw err;
        }
        return j;
      });
    });
};

function isFinished(d){
  if(!d) return false;
  if(d.download_finished === true) return true;
  if(d.download_finished === false) return false;
  return d.download_state === "completed" || d.download_state === "cached" || d.progress === 1;
}
tb.isFinished = isFinished;

/* Cache en memoria de 60 s para no repetir peticiones al cambiar de pantalla */
var cache = {};
tb.invalidate = function(){ cache = {}; };

tb.list = function(source, opts){
  opts = opts || {};
  var ck = source + (opts.all ? ":all" : "");
  var c = cache[ck];
  if(c && Date.now() - c.t < 60000 && !opts.fresh) return Promise.resolve(c.v);
  return tb.api("/" + source + "/mylist?bypass_cache=" + (opts.fresh ? "true" : "false"))
    .then(function(j){
      var data = j.data || [];
      if(!Array.isArray(data)) data = [data];
      data.forEach(function(d){ if(d) d._source = source; });
      if(!opts.all){
        data = data.filter(function(d){ return d && d.files && d.files.length && isFinished(d); });
      }
      cache[ck] = { t: Date.now(), v: data };
      return data;
    });
};

/* Las 3 fuentes juntas; una fuente que falle no tumba las demás. */
tb.allLibrary = function(opts){
  return Promise.all(tb.SOURCES.map(function(s){
    return tb.list(s, opts).catch(function(e){ console.warn("[torbox] " + s, e); return []; });
  })).then(function(lists){
    var out = [];
    lists.forEach(function(l){ out = out.concat(l); });
    out.sort(function(a, b){
      return String(b.created_at || b.updated_at || "").localeCompare(String(a.created_at || a.updated_at || ""));
    });
    return out;
  });
};

tb.link = function(source, itemId, fileId){
  var q = "/" + source + "/requestdl?token=" + encodeURIComponent(token()) +
          "&" + tb.ID_FIELD[source] + "=" + encodeURIComponent(itemId) +
          "&file_id=" + encodeURIComponent(fileId) + "&redirect=false";
  return App.net.fetch(API + q).then(function(r){ return r.json(); }).then(function(j){
    if(j.success === false || !j.data) throw new Error(j.detail || App.t("torbox.noLink"));
    return j.data;
  });
};

/* ---------------- Añadir / controlar (campos según api.torbox.app/openapi.json) ---------------- */

/* checkCached(hashes) → Promise<{hash: true}> */
tb.checkCached = function(hashes){
  hashes = (hashes || []).filter(Boolean).slice(0, 100);
  if(!hashes.length) return Promise.resolve({});
  return tb.api("/torrents/checkcached?hash=" + encodeURIComponent(hashes.join(",")) +
                "&format=object&list_files=false").then(function(j){
    var out = {}, d = j.data;
    if(Array.isArray(d)) d.forEach(function(x){ if(x && x.hash) out[String(x.hash).toLowerCase()] = true; });
    else if(d && typeof d === "object") Object.keys(d).forEach(function(h){ if(d[h]) out[h.toLowerCase()] = true; });
    return out;
  });
};

tb.addMagnet = function(magnet, name){
  return tb.api("/torrents/createtorrent", { method: "POST", form: { magnet: magnet, name: name || undefined } })
    .then(function(j){ tb.invalidate(); return j.data || {}; });
};
tb.addUsenet = function(link, name){
  return tb.api("/usenet/createusenetdownload", { method: "POST", form: { link: link, name: name || undefined } })
    .then(function(j){ tb.invalidate(); return j.data || {}; });
};
tb.addWeb = function(link, name){
  return tb.api("/webdl/createwebdownload", { method: "POST", urlencoded: { link: link, name: name || undefined } })
    .then(function(j){ tb.invalidate(); return j.data || {}; });
};
/* Detecta el tipo de enlace: magnet / hash → torrent, .nzb → usenet, resto → descarga web */
tb.linkKind = function(link){
  link = String(link || "").trim();
  if(/^magnet:\?/i.test(link) || /^[a-f0-9]{40}$/i.test(link)) return "torrents";
  if(/\.nzb(\?|$)/i.test(link) || /nzb/i.test(link.split("?")[0].split("/").pop() || "")) return "usenet";
  if(/^https?:\/\//i.test(link)) return "webdl";
  return null;
};
tb.addLink = function(link, name){
  link = String(link || "").trim();
  var kind = tb.linkKind(link);
  if(kind === "torrents"){
    if(/^[a-f0-9]{40}$/i.test(link)) link = "magnet:?xt=urn:btih:" + link;
    return tb.addMagnet(link, name).then(function(d){ return { kind: kind, data: d }; });
  }
  if(kind === "usenet") return tb.addUsenet(link, name).then(function(d){ return { kind: kind, data: d }; });
  if(kind === "webdl") return tb.addWeb(link, name).then(function(d){ return { kind: kind, data: d }; });
  return Promise.reject(new Error(App.t("torbox.badLink")));
};

/* control(source, id, operation): operation ∈ delete | pause | resume | reannounce */
var CONTROL = {
  torrents: { path: "/torrents/controltorrent", field: "torrent_id" },
  usenet:   { path: "/usenet/controlusenetdownload", field: "usenet_id" },
  webdl:    { path: "/webdl/controlwebdownload", field: "webdl_id" }
};
tb.control = function(source, id, operation){
  var c = CONTROL[source];
  if(!c) return Promise.reject(new Error(App.t("torbox.badSource")));
  var body = { operation: operation };
  body[c.field] = id;
  return tb.api(c.path, { method: "POST", body: body }).then(function(j){ tb.invalidate(); return j; });
};

/* Clave estable para historial */
tb.key = function(source, itemId, fileId){ return source + ":" + itemId + ":" + fileId; };

})();

}catch(__e){ if(window.console) console.error("[bundle] js/torbox.js", __e); }
;
/* ==== js/debrid-rd.js ==== */
try{
/* debrid-rd.js — compatibilidad con Real-Debrid, A LA VEZ que TorBox.
 *
 * Real-Debrid es una fuente más ("rd") junto a torrents/usenet/webdl de TorBox: App.torbox.SOURCES
 * incluye las de cada cuenta configurada (torboxToken y/o rdToken) y list/link/control se enrutan por
 * la fuente de cada item. Los datos de Real-Debrid se devuelven con la MISMA forma que TorBox
 * (files[], download_finished, progress 0–1…), así que las pantallas no cambian.
 * `debridProvider` ("torbox" | "realdebrid") = cuenta a la que se AÑADEN los torrents nuevos.
 *
 * API: https://api.real-debrid.com/rest/1.0 (Bearer token, CORS abierto).
 * Limitaciones de Real-Debrid: sin Usenet, sin pausar/reanudar, y desde nov. 2024 no ofrece
 * consulta de caché (instantAvailability) → checkCached devuelve {}.
 */
(function(){
"use strict";
var App = window.App;
var API = "https://api.real-debrid.com/rest/1.0";
var tb = App.torbox;

App.settings.define("debridProvider", "torbox");
App.settings.define("rdToken", "");

function isRD(){ return App.settings.get("debridProvider") === "realdebrid"; }
function rdToken(){ return App.settings.get("rdToken") || ""; }

function hasTB(){ return !!(App.settings.get("torboxToken") || ""); }
function hasRDt(){ return !!rdToken(); }
/* Cuenta destino para añadir: la elegida si está configurada; si no, la que haya */
function addToRD(){ return (isRD() && hasRDt()) || (!hasTB() && hasRDt()); }

App.debrid = {
  provider: function(){ return addToRD() ? "realdebrid" : "torbox"; },
  name: function(){ return addToRD() ? "Real-Debrid" : "TorBox"; },
  isRD: isRD,
  hasTorbox: hasTB,
  hasRD: hasRDt,
  rdAccount: function(){ return RD.account().then(function(j){ return j.data; }); }
};

/* ---------- Llamadas ---------- */
function rd(path, opts){
  opts = opts || {};
  var headers = { "Authorization": "Bearer " + rdToken() };
  var body;
  if(opts.form){
    headers["Content-Type"] = "application/x-www-form-urlencoded";
    body = Object.keys(opts.form).map(function(k){ return encodeURIComponent(k) + "=" + encodeURIComponent(opts.form[k]); }).join("&");
  }
  return App.net.fetch(API + path, { method: opts.method || "GET", headers: headers, body: body }).then(function(r){
    if(r.status === 204) return {};
    return r.text().then(function(txt){
      var j; try{ j = txt ? JSON.parse(txt) : {}; }catch(e){ j = { error: txt }; }
      if(!r.ok){
        var err = new Error((j && (j.error || j.message)) || ("HTTP " + r.status));
        err.status = r.status; err.body = j;
        console.warn("[Real-Debrid] " + (opts.method || "GET") + " " + path.split("?")[0] + " → " + r.status + " " + err.message);
        throw err;
      }
      return j;
    });
  });
}

/* ---------- Conversión al formato de TorBox ---------- */
var STATE = {
  downloaded: "completed", downloading: "downloading", queued: "queued", uploading: "uploading",
  compressing: "downloading", magnet_conversion: "metaDL", waiting_files_selection: "metaDL",
  magnet_error: "error", error: "error", virus: "error", dead: "stalled (no seeds)"
};
var infoCache = {};   // id → info (los torrents terminados no cambian)

function toItem(t, info){
  var done = t.status === "downloaded";
  var files = [];
  if(info && info.files){
    info.files.filter(function(f){ return f.selected; }).forEach(function(f){
      var name = String(f.path || "").replace(/^\//, "");
      files.push({ id: f.id, name: name, short_name: name.split("/").pop(), size: f.bytes });
    });
  }
  var added = t.added ? new Date(t.added).toISOString() : "";
  return {
    id: t.id, hash: String(t.hash || "").toLowerCase(), name: t.filename || t.original_filename || t.id,
    size: t.bytes || 0, files: files,
    download_finished: done, download_state: STATE[t.status] || t.status,
    progress: (Number(t.progress) || 0) / 100, download_speed: t.speed || 0,
    eta: (t.speed && t.bytes && t.progress < 100) ? Math.round(t.bytes * (1 - t.progress / 100) / t.speed) : 0,
    seeds: t.seeders || 0, created_at: added, updated_at: t.ended || added,
    _source: "rd", _rd: true
  };
}

function info(id){
  if(infoCache[id]) return Promise.resolve(infoCache[id]);
  return rd("/torrents/info/" + encodeURIComponent(id)).then(function(j){
    if(j && j.status === "downloaded") infoCache[id] = j;
    return j;
  });
}

/* Cola simple para no lanzar decenas de peticiones a la vez */
function mapLimit(arr, n, fn){
  var out = new Array(arr.length), i = 0;
  function worker(){
    if(i >= arr.length) return Promise.resolve();
    var k = i++;
    return Promise.resolve(fn(arr[k], k)).then(function(v){ out[k] = v; }, function(){ out[k] = null; }).then(worker);
  }
  var ws = []; for(var w = 0; w < Math.min(n, arr.length); w++) ws.push(worker());
  return Promise.all(ws).then(function(){ return out; });
}

var listCache = null;
var RD = {
  hasToken: function(){ return !!rdToken(); },
  invalidate: function(){ listCache = null; },
  list: function(source, opts){
    opts = opts || {};
    if(source !== "rd" || !hasRDt()) return Promise.resolve([]);
    if(listCache && Date.now() - listCache.t < 60000 && !opts.fresh){
      return Promise.resolve(opts.all ? listCache.all : listCache.all.filter(function(d){ return d.download_finished && d.files.length; }));
    }
    return rd("/torrents?limit=200").then(function(arr){
      arr = Array.isArray(arr) ? arr : [];
      return mapLimit(arr, 4, function(t){
        return t.status === "downloaded" ? info(t.id).then(function(inf){ return toItem(t, inf); }) : toItem(t, null);
      });
    }).then(function(items){
      items = items.filter(Boolean);
      listCache = { t: Date.now(), all: items };
      return opts.all ? items : items.filter(function(d){ return d.download_finished && d.files.length; });
    });
  },
  /* Enlace de reproducción: el link "restringido" del archivo → /unrestrict/link */
  link: function(source, itemId, fileId){
    return info(itemId).then(function(inf){
      var sel = (inf.files || []).filter(function(f){ return f.selected; });
      var idx = -1;
      sel.forEach(function(f, i){ if(String(f.id) === String(fileId)) idx = i; });
      var links = inf.links || [];
      // Si Real-Debrid empaquetó en un único enlace (RAR), solo hay uno
      var restricted = links[idx] || (links.length === 1 ? links[0] : null);
      if(!restricted) throw new Error(App.t("rd.noLink"));
      return rd("/unrestrict/link", { method: "POST", form: { link: restricted } });
    }).then(function(u){
      if(!u || !u.download) throw new Error(App.t("rd.noLink"));
      return u.download;
    });
  },
  checkCached: function(){ return Promise.resolve({}); },
  addMagnet: function(magnet){
    return rd("/torrents/addMagnet", { method: "POST", form: { magnet: magnet } }).then(function(j){
      if(!j || !j.id) throw new Error(App.t("rd.addFailed"));
      // Real-Debrid exige elegir archivos: se eligen todos
      return rd("/torrents/selectFiles/" + encodeURIComponent(j.id), { method: "POST", form: { files: "all" } })
        .catch(function(e){ console.warn("[Real-Debrid] selectFiles:", e.message); })
        .then(function(){ RD.invalidate(); return { id: j.id, hash: "" }; });
    });
  },
  addLink: function(link, name){
    link = String(link || "").trim();
    var kind = tb.linkKind(link);
    if(kind === "torrents"){
      if(/^[a-f0-9]{40}$/i.test(link)) link = "magnet:?xt=urn:btih:" + link;
      return RD.addMagnet(link, name).then(function(d){ return { kind: kind, data: d }; });
    }
    return Promise.reject(new Error(App.t("rd.onlyTorrents")));
  },
  control: function(source, id, operation){
    if(operation === "delete"){
      delete infoCache[id];
      return rd("/torrents/delete/" + encodeURIComponent(id), { method: "DELETE" }).then(function(j){ RD.invalidate(); return j; });
    }
    return Promise.reject(new Error(App.t("rd.notSupported")));
  },
  /* Cuenta: se traduce al formato de /user/me de TorBox que usa Ajustes */
  account: function(){
    return rd("/user").then(function(u){
      return { data: {
        plan: u.type === "premium" ? "rd_premium" : "rd_free",
        premium_expires_at: u.expiration || null,
        email: u.email || "", username: u.username || "", points: u.points
      } };
    });
  }
};

/* ---------- Enrutado: Real-Debrid es la fuente "rd"; lo demás sigue en TorBox ---------- */
tb.SOURCE_LABEL.rd = "Real-Debrid";
var TB_SOURCES = tb.SOURCES.slice();
Object.defineProperty(tb, "SOURCES", {
  configurable: true,
  get: function(){
    var out = hasTB() ? TB_SOURCES.slice() : [];
    if(hasRDt()) out.push("rd");
    return out.length ? out : TB_SOURCES.slice();
  }
});
var O = {};
["hasToken", "invalidate", "list", "link", "checkCached", "addMagnet", "addLink", "control", "addUsenet", "addWeb", "api"]
  .forEach(function(m){ O[m] = tb[m]; });
tb.hasToken = function(){ return hasTB() || hasRDt(); };
tb.invalidate = function(){ RD.invalidate(); return O.invalidate.apply(tb, arguments); };
tb.list = function(source){ return source === "rd" ? RD.list.apply(RD, arguments) : O.list.apply(tb, arguments); };
tb.link = function(source){ return source === "rd" ? RD.link.apply(RD, arguments) : O.link.apply(tb, arguments); };
tb.control = function(source){ return source === "rd" ? RD.control.apply(RD, arguments) : O.control.apply(tb, arguments); };
tb.checkCached = function(){ return hasTB() ? O.checkCached.apply(tb, arguments) : Promise.resolve({}); };
tb.addMagnet = function(){ return addToRD() ? RD.addMagnet.apply(RD, arguments) : O.addMagnet.apply(tb, arguments); };
/* addMagnetTo("RD"|"TB"|"", magnet, name): manda a la cuenta que indica la fuente del add-on ("[RD⬇️]"→RD);
 * si esa cuenta no está configurada (o no se sabe), a la cuenta destino de siempre. */
tb.rdUser = function(){ return rd("/user"); };   // comprobación de la clave (checks.js)
tb.addMagnetTo = function(svc, magnet, name){
  if(svc === "RD" && hasRDt()) return RD.addMagnet(magnet, name);
  if(svc === "TB" && hasTB()) return O.addMagnet.call(tb, magnet, name);
  return tb.addMagnet(magnet, name);
};
tb.addLink = function(link){
  // Usenet y descargas web solo existen en TorBox; los magnets van a la cuenta destino
  if(addToRD() && tb.linkKind(link) === "torrents") return RD.addLink.apply(RD, arguments);
  if(!hasTB()) return RD.addLink.apply(RD, arguments);
  return O.addLink.apply(tb, arguments);
};
tb.addUsenet = function(){ return hasTB() ? O.addUsenet.apply(tb, arguments) : Promise.reject(new Error(App.t("rd.onlyTorrents"))); };
tb.addWeb = function(){ return hasTB() ? O.addWeb.apply(tb, arguments) : Promise.reject(new Error(App.t("rd.onlyTorrents"))); };
tb.api = function(path){
  if(!hasTB() && /^\/user\/me/.test(String(path))) return RD.account();
  if(!hasTB()) return Promise.reject(new Error(App.t("rd.notSupported")));
  return O.api.apply(tb, arguments);
};

App.bus.on("settings:change", function(c){
  if(c && (c.key === "debridProvider" || c.key === "rdToken")){ RD.invalidate(); tb.invalidate(); infoCache = {}; }
});

/* ---------- Ajustes ---------- */
if(App.settingsUI){
  App.settingsUI.add("settings.group.account", {
    id: "debridProvider", type: "menu",
    label: function(){ return App.t("rd.provider"); },
    desc: function(){ return App.t("rd.provider.desc"); },
    options: function(){ return [{ label: "TorBox", value: "torbox" }, { label: "Real-Debrid", value: "realdebrid" }]; },
    value: function(){ return App.debrid.name(); },
    after: function(){ tb.invalidate(); }
  });
  App.settingsUI.add("settings.group.account", {
    id: "rdToken", type: "secret",
    label: function(){ return App.t("rd.token"); },
    desc: function(){ return App.t("rd.token.desc"); },
    value: function(){ var v = rdToken(); return v ? v.slice(0, 4) + "••••" + v.slice(-4) : App.t("rd.notSet"); },
    after: function(){ tb.invalidate(); }
  });
}
})();

}catch(__e){ if(window.console) console.error("[bundle] js/debrid-rd.js", __e); }
